package com.trackspeed.android.data

import android.content.ContentValues
import android.database.sqlite.SQLiteDatabase
import androidx.room.Room
import androidx.test.ext.junit.runners.AndroidJUnit4
import androidx.test.platform.app.InstrumentationRegistry
import com.trackspeed.android.data.local.TrackSpeedDatabase
import kotlinx.coroutines.runBlocking
import org.junit.Assert.*
import org.junit.Test
import org.junit.runner.RunWith
import java.util.UUID

/** Frozen schema emitted by Room2.6.1 at4be82d9, not regenerated by the new compiler. */
@RunWith(AndroidJUnit4::class)
class RoomVersionNineCompatibilityTest {
    @Test fun previousRoomVersionNineDataSurvivesOpenWriteAndReopen() = runBlocking {
        val instrumentation = InstrumentationRegistry.getInstrumentation()
        val context = instrumentation.targetContext
        val name = "room-compat-${UUID.randomUUID()}.db"
        val file = context.getDatabasePath(name)
        file.parentFile!!.mkdirs()
        var database: TrackSpeedDatabase? = null
        try {
            SQLiteDatabase.openOrCreateDatabase(file, null).use { old ->
                instrumentation.context.assets.open("room-2.6.1-version9.sql").bufferedReader().useLines { lines ->
                    lines.filter { it.isNotBlank() && !it.startsWith("--") }.forEach(old::execSQL)
                }
                old.version = 9
                old.insertOrThrow("training_sessions", null, ContentValues().apply {
                    put("id", "legacy"); put("date", 1L); put("distance", 30.0); put("startType", "flying")
                    put("numberOfPhones", 2); put("numberOfGates", 2); put("createdAt", 1L); put("updatedAt", 1L)
                })
                old.insertOrThrow("runs", null, ContentValues().apply {
                    put("id", "legacy-run"); put("sessionId", "legacy"); put("runNumber", 1)
                    put("timeSeconds", 2.931234567); put("distance", 30.0); put("startType", "flying")
                    put("numberOfPhones", 2); put("isPersonalBest", 1); put("isSeasonBest", 1)
                    put("gatePosition", .5); put("crossingTimestampNanos", 9_000_000_000_001L)
                    put("createdAt", 1L); put("athleteName", "Synthetic retained athlete")
                })
            }
            database = Room.databaseBuilder(context, TrackSpeedDatabase::class.java, name).build()
            val original = database!!.runDao().getRunById("legacy-run")!!
            assertEquals(2.931234567, original.timeSeconds, 0.0)
            assertEquals(9_000_000_000_001L, original.crossingTimestampNanos)
            assertEquals("Synthetic retained athlete", original.athleteName)
            assertTrue(original.isPersonalBest)
            database!!.runDao().updateDistance("legacy-run", 40.0)
            database!!.close(); database = null
            database = Room.databaseBuilder(context, TrackSpeedDatabase::class.java, name).build()
            val reopened = database!!.runDao().getRunById("legacy-run")!!
            assertEquals(40.0, reopened.distance, 0.0)
            assertEquals(original.timeSeconds, reopened.timeSeconds, 0.0)
            assertEquals(original.crossingTimestampNanos, reopened.crossingTimestampNanos)
            assertFalse(reopened.isPersonalBest)
            assertFalse(reopened.isSeasonBest)
        } finally {
            database?.close()
            context.deleteDatabase(name) // Only the unique fixture created by this test.
        }
    }
}
